select framed_ip, arraySlice(groupUniqArray(concat(toString(event_timestamp),':', if(acct_status_type=1,'start','stop'))),1,100000) as timeseries from radius_onff_log where event_timestamp >=toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)) and event_timestamp <toDateTime(now()) group by framed_ip limit 20
select account, arraySlice(groupUniqArray(concat(toString(event_timestamp),':', if(acct_status_type=1,'start','stop'))),1,100000) as timeseries from radius_onff_log where event_timestamp >= toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)) and event_timestamp < toDateTime(now())  group by account
select count(distinct(framed_ip)) as active_ip_num , sum(acct_session_time) as online_duration from (select any(framed_ip) as framed_ip ,max(acct_session_time) as acct_session_time from radius_onff_log where account='000jS' and event_timestamp >= toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)) and event_timestamp < toDateTime(now())  group by acct_session_id)
select max(if(acct_status_type=1,event_timestamp,0)) as start_time,max(if(acct_status_type=2,event_timestamp,0)) as end_time, any(framed_ip) as ip,max(acct_session_time) as online_duration  from radius_onff_log where event_timestamp >= toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)) and event_timestamp < toDateTime(now())  group by acct_session_id  order by start_time desc limit 200
select common_client_ip, count(*) as sessions from session_record where common_recv_time>= toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)))-604800 and common_recv_time< toStartOfDay(toDateTime(now()))  group by common_client_ip order by sessions desc limit 0,100
select common_server_ip, count(*) as sessions from session_record where common_recv_time>= toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)))-604800 and common_recv_time< toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)))  group by common_server_ip order by sessions desc limit 0,100
select ssl_sni, count(*) as sessions from session_record where common_recv_time>= toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)))-604800 and common_recv_time< toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)))  group by ssl_sni order by sessions desc limit 0,100
select common_app_label as applicaiton, count(*) as sessions from session_record where common_recv_time>= toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)))-604800 and common_recv_time< toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)))  group by applicaiton order by sessions desc limit 0,100
select http_domain AS domain,SUM(coalesce(common_c2s_byte_num, 0)) AS sent_bytes,SUM(coalesce(common_s2c_byte_num, 0)) AS received_bytes,SUM(coalesce(common_c2s_byte_num, 0)+coalesce(common_s2c_byte_num, 0)) AS bytes FROM session_record WHERE common_recv_time >= toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)))-86400 AND common_recv_time < toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600))) and notEmpty(domain)  GROUP BY domain ORDER BY bytes DESC LIMIT 100
select toDateTime(intDiv(toUInt32(toDateTime(toDateTime(common_recv_time))), 300)*300) as stat_time, http_domain, uniq (common_client_ip) as nums  from session_record where common_recv_time >= toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)))-86400 AND common_recv_time < toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)))  and http_domain in (select http_domain from session_record where common_recv_time >= toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)))-86400 AND common_recv_time < toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)))  and notEmpty(http_domain) group by http_domain order by SUM(coalesce(common_c2s_byte_num, 0)+coalesce(common_s2c_byte_num, 0)) desc limit 10 ) group by toDateTime(intDiv(toUInt32(toDateTime(toDateTime(common_recv_time))), 300)*300), http_domain order by stat_time asc limit 500
SELECT http_host as host, SUM(coalesce(common_c2s_byte_num, 0)) AS sent_bytes,SUM(coalesce(common_s2c_byte_num, 0)) AS received_bytes,SUM(coalesce(common_c2s_byte_num, 0)+coalesce(common_s2c_byte_num, 0)) AS bytes FROM session_record WHERE common_recv_time>= toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)))-604800 and common_recv_time< toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)))  and notEmpty(http_host) GROUP BY host ORDER BY bytes DESC limit 100 union all SELECT  'totals'  as host, SUM(coalesce(common_c2s_byte_num, 0)) AS sent_bytes, SUM(coalesce(common_s2c_byte_num, 0)) AS received_bytes, SUM(coalesce(common_c2s_byte_num, 0)+coalesce(common_s2c_byte_num, 0)) AS bytes from session_record where common_recv_time>= toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)))-604800 and common_recv_time< toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)))  and notEmpty(http_host)
SELECT http_url AS url,count(*) AS sessions FROM proxy_event WHERE common_recv_time >= toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)))-86400 AND common_recv_time < toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600))) and notEmpty(http_url) GROUP BY url ORDER BY sessions DESC LIMIT 100
select toDateTime(intDiv(toUInt32(toDateTime(toDateTime(common_recv_time))), 300)*300) as stat_time, http_url, count(distinct(common_client_ip)) as nums  from proxy_event where common_recv_time >= toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)))-86400 AND common_recv_time < toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600))) and http_url IN (select http_url from proxy_event where common_recv_time >= toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)))-86400 AND common_recv_time < toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600))) and notEmpty(http_url)  group by http_url order by count(*) desc limit 10 ) group by toDateTime(intDiv(toUInt32(toDateTime(toDateTime(common_recv_time))), 300)*300), http_url order by stat_time asc limit 500
select common_subscriber_id as user, count(*) as sessions from session_record where common_recv_time>= toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)))-604800 and common_recv_time< toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)))  and notEmpty(user)   group by common_subscriber_id order by sessions desc limit 0,100
SELECT common_subscriber_id as user,SUM(coalesce(common_c2s_byte_num, 0)) AS sent_bytes,SUM(coalesce(common_s2c_byte_num, 0)) AS received_bytes,SUM(coalesce(common_c2s_byte_num, 0)+coalesce(common_s2c_byte_num, 0)) AS bytes FROM session_record WHERE common_recv_time>= toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)))-604800 and common_recv_time< toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600))) and notEmpty(user)   GROUP BY user ORDER BY bytes  DESC LIMIT 100
select uniq(common_client_ip) as "Client IP",uniq(common_server_ip) as "Server IP",uniq(common_internal_ip) as "Internal IP",uniq(common_external_ip) as "External IP",uniq(http_domain) as "Domain",uniq(ssl_sni) as "SNI"  from session_record where common_recv_time>= toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)))-604800 and common_recv_time< toStartOfDay(toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)))
SELECT http_url AS url, SUM(common_sessions) AS sessions FROM session_record WHERE common_recv_time >= toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)) AND common_recv_time < toDateTime(now()) AND notEmpty(http_url) GROUP BY http_url ORDER BY sessions DESC limit 10
select DATE_FORMAT(FROM_UNIXTIME(FLOOR(UNIX_TIMESTAMP(__time)/300)*300),'%Y-%m-%d %H:%i:%s') as start_time, sum(hits) as hits from security_event_hits_log where __time >= FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600) and __time < now() group by DATE_FORMAT(FROM_UNIXTIME(FLOOR(UNIX_TIMESTAMP(__time)/300)*300),'%Y-%m-%d %H:%i:%s') limit 10000
select policy_id, DATE_FORMAT(min(__time) ,'%Y-%m-%d %H:%i:%s')  as first_used,  DATE_FORMAT(max(__time) ,'%Y-%m-%d %H:%i:%s') as last_used from security_event_hits_log where policy_id in (0) group by policy_id
select FROM_UNIXTIME(FLOOR(UNIX_TIMESTAMP(__time)/300)*300) as start_time, sum(hits) as hits from proxy_event_hits_log where __time >= FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600) and __time < now()  group by  FROM_UNIXTIME(FLOOR(UNIX_TIMESTAMP(__time)/300)*300) limit 10000
select policy_id, DATE_FORMAT(min(__time) ,'%Y-%m-%d %H:%i:%s')  as first_used,  DATE_FORMAT(max(__time) ,'%Y-%m-%d %H:%i:%s') as last_used from  proxy_event_hits_log where policy_id in (0) group by policy_id
(SELECT TIME_FORMAT(MILLIS_TO_TIMESTAMP( 1000 * TIME_FLOOR_WITH_FILL(TIMESTAMP_TO_MILLIS(__time)/1000, 'PT30S', 'zero')), 'yyyy-MM-dd HH:mm:ss') as stat_time, protocol_id as type, sum(c2s_byte_num + s2c_byte_num) as bytes from traffic_protocol_stat_log where __time >= FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600) AND __time < now() and protocol_id = 'ETHERNET' group by TIME_FORMAT(MILLIS_TO_TIMESTAMP( 1000 * TIME_FLOOR_WITH_FILL(TIMESTAMP_TO_MILLIS(__time)/1000, 'PT30S', 'zero')), 'yyyy-MM-dd HH:mm:ss'), protocol_id order by stat_time asc) union all (SELECT TIME_FORMAT(MILLIS_TO_TIMESTAMP( 1000 * TIME_FLOOR_WITH_FILL(TIMESTAMP_TO_MILLIS(__time)/1000, 'PT30S', 'zero')), 'yyyy-MM-dd HH:mm:ss') as stat_time, protocol_id as type, sum(c2s_byte_num + s2c_byte_num) as bytes from traffic_protocol_stat_log where __time >= FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600) AND __time < now()  and protocol_id like CONCAT('ETHERNET','.%') and LENGTH(protocol_id) = LENGTH(REPLACE(protocol_id,'.','')) + 1 + 0 group by TIME_FORMAT(MILLIS_TO_TIMESTAMP( 1000 * TIME_FLOOR_WITH_FILL(TIMESTAMP_TO_MILLIS(__time)/1000, 'PT30S', 'zero')), 'yyyy-MM-dd HH:mm:ss'), protocol_id order by stat_time asc)
select FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time),'PT1800S','zero'))  as statisticTime, sum(default_in_bytes + default_out_bytes) as default_bytes, sum(default_in_packets + default_out_packets) as default_packets, sum(default_conn_num) as default_sessions, sum(allow_in_bytes + allow_out_bytes) as allow_bytes, sum(allow_in_packets + allow_out_packets) as allow_packets, sum(allow_conn_num) as allow_sessions, sum(deny_in_bytes + deny_out_bytes) as deny_bytes, sum(deny_in_packets + deny_out_packets) as deny_packets, sum(deny_conn_num) as deny_sessions, sum(monitor_in_bytes + monitor_out_bytes) as monitor_bytes, sum(monitor_in_packets + monitor_out_packets) as monitor_packets, sum(monitor_conn_num) as monitor_sessions, sum(intercept_in_bytes + intercept_out_bytes) as intercept_bytes, sum(intercept_in_packets + intercept_out_packets) as intercept_packets, sum(intercept_conn_num) as intercept_sessions from traffic_metrics_log where __time >= FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600) and __time < now() group by FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time),'PT1800S','zero')) limit 100000
SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time),'PT1800S','zero')) AS statisticTime,SUM(intcp_allow_num) AS intercept_allow_conn_num,SUM(intcp_mon_num) AS intercept_monitor_conn_num,SUM(intcp_deny_num) AS intercept_deny_conn_num,SUM(intcp_rdirt_num) AS intercept_redirect_conn_num,SUM(intcp_repl_num) AS intercept_replace_conn_num,SUM(intcp_hijk_num) AS intercept_hijack_conn_num,SUM(intcp_ins_num) AS intercept_insert_conn_num FROM traffic_metrics_log WHERE __time >= FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600) AND __time < now() GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), 'PT1800S', 'zero')) LIMIT 100000
select FROM_UNIXTIME(stat_time) as max_active_date_by_sessions, total_live_sessions as max_live_sessions from ( select stat_time, sum(live_sessions) as total_live_sessions from ( select TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), 'P1D') as stat_time, device_id, avg(established_conn_num) as live_sessions from traffic_metrics_log where __time >= FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600) and __time<now() group by TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), 'P1D'), device_id) group by stat_time order by total_live_sessions desc limit 1 )
select * from ( select DATE_FORMAT(FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time),'PT1h','zero')),'%Y-%m-%d %H:%i:%s') as stat_time,'traffic_in_bytes' as type, sum(total_in_bytes) as bytes from traffic_metrics_log where __time >= FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600) and __time < now() group by DATE_FORMAT(FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time),'PT1h','zero')),'%Y-%m-%d %H:%i:%s'), 'traffic_in_bytes' union all select DATE_FORMAT(FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time),'PT1h','zero')),'%Y-%m-%d %H:%i:%s') as stat_time,'traffic_out_bytes' as type,sum(total_out_bytes) as bytes from traffic_metrics_log where __time >= FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600) and __time < now() group by DATE_FORMAT(FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time),'PT1h','zero')),'%Y-%m-%d %H:%i:%s'),'traffic_out_bytes' ) order by stat_time asc limit 100000
select DATE_FORMAT(FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time),'PT1h','zero')),'%Y-%m-%d %H:%i:%s') as stat_time, 'total_conn_num' as type, sum(new_conn_num) as sessions from traffic_metrics_log where __time >= FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600) and __time < now() group by DATE_FORMAT(FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time),'PT1h','zero')),'%Y-%m-%d %H:%i:%s'), 'total_conn_num' order by stat_time asc limit 10000
select FROM_UNIXTIME(min(common_recv_time)) as "First Seen" , FROM_UNIXTIME(max(common_recv_time)) as "Last Seen" ,  median(http_response_latency_ms) as "Server Processing Time Median(ms)", count(1) as Responses,any(common_server_location)  as Location from session_record WHERE  common_recv_time >= toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)) AND common_recv_time < toDateTime(now())  AND  http_domain='baidu.com'
select "Device Group" as "Device Group" ,"Data Center" as "Data Center" ,FROM_UNIXTIME("End Time") as "End Time" , sum("counter") as "counter"  from (select common_device_group as "Device Group" ,common_data_center as "Data Center" ,TIME_FLOOR_WITH_FILL (common_end_time,'PT1H','zero') as "End Time" ,count(common_log_id) as "counter"  from session_record where   common_recv_time >= toDateTime(FROM_UNIXTIME(UNIX_TIMESTAMP(now())-3600)) and common_recv_time< toDateTime(now())  group by "Device Group","Data Center","End Time") group by "Device Group" ,"Data Center" ,"End Time"  order by  "End Time" asc  limit 5
select FROM_UNIXTIME("End Time") as "End Time" , sum("counter") as "counter"  from (select common_device_group as "Device Group" ,common_data_center as "Data Center" ,TIME_FLOOR_WITH_FILL (common_end_time,'PT1H','zero') as "End Time" ,count(common_log_id) as "counter" ,count(http_domain) as "HTTP.Domain"  from security_event where   ((common_recv_time >= toDateTime('2021-10-19 00:00:00') and common_recv_time < toDateTime('2021-10-20 00:00:00'))  )  AND (  ( common_action = 2  ) ) group by "Device Group","Data Center","End Time") group by "End Time"  order by  "End Time" asc
